// SAROpenAndFill opens a stream as [Core.SAROpen] does and also writes the
// outputs over the whole history, as [Core.SAR] writes them for bars 0 through
// len(inHigh)-1, returning that range.
//
// Each output must hold len(inHigh) minus [Core.SARLookback] values and share
// no memory with an input or another output.
//
// The errors are those of [Core.SAROpen], and [BadParam] for an output that is
// empty, too short or sharing memory. A slice whose capacity a three-index
// expression cut, as slices.Clip does, can escape the sharing check.
func (c *Core) SAROpenAndFill(inHigh, inLow []float64, optInAcceleration, optInMaximum float64, outReal []float64) (*SARStream, OutRange, error) {
	if len(inHigh) > IndexMax+1 {
		return nil, OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.sarLookback(optInAcceleration, optInMaximum))
	if lookback < 0 {
		return nil, OutRange{}, BadParam
	}
	if len(inLow) != len(inHigh) {
		return nil, OutRange{}, BadParam
	}
	outLen := max(len(inHigh)-lookback, 0)
	if len(outReal) == 0 || len(outReal) < outLen {
		return nil, OutRange{}, BadParam
	}
	if sameStart(outReal, inHigh) || sameStart(outReal, inLow) {
		return nil, OutRange{}, BadParam
	}
	if outLen > 0 && (overlaps(outReal, inHigh) || overlaps(outReal, inLow)) {
		return nil, OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	sp, err := c.sarOpenAndFillInternal(inHigh, inLow, 0, optInAcceleration, optInMaximum, &outBegIdx, &outNBElement, outReal)
	if err != nil {
		return nil, OutRange{}, err
	}
	return sp, OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}
